-- See https://wiki.hyprland.org/Configuring/Keywords/ for more settings and variables
-- See also Laptops.conf for laptops keybinds 

-- Generated by hyprlang2lua. Review TODOs before reloading Hyprland.

local HOME = os.getenv("HOME") or ""
local mainMod = "SUPER"
local files = "thunar"
local term = "kitty"
local scriptsDir = HOME .. "/.config/hypr/scripts"
local UserScripts = HOME .. "/.config/hypr/UserScripts"

-- rofi App launcher
--bindr = $mainMod, $mainMod_L, exec, pkill rofi || rofi -show drun -modi drun,filebrowser,run,window
hl.bind(mainMod .. " + D", hl.dsp.exec_cmd("pkill rofi || rofi -show drun -modi drun,filebrowser,run,window"))

hl.bind(mainMod .. " + Return", hl.dsp.exec_cmd(term))
hl.bind(mainMod .. " + T", hl.dsp.exec_cmd(files))

-- User Added Keybinds
hl.bind(mainMod .. " + SHIFT + O", hl.dsp.exec_cmd(UserScripts .. "/ZshChangeTheme.sh"))

-- Toggle focus between tiled and floating windows
hl.bind(mainMod .. " + space", function()
    local win = hl.get_active_window()
    if win and win.floating then
        hl.dispatch(hl.dsp.window.cycle_next({ tiled = true }))
    else
        hl.dispatch(hl.dsp.window.cycle_next({ floating = true }))
    end
end)

-- move focused window
-- mainMod + H/L/K/J are not bound elsewhere; safe to bind directly.
hl.bind(mainMod .. " + H", hl.dsp.focus({ direction = "left" }))
hl.bind(mainMod .. " + L", hl.dsp.focus({ direction = "right" }))
hl.bind(mainMod .. " + K", hl.dsp.focus({ direction = "up" }))
hl.bind(mainMod .. " + J", hl.dsp.focus({ direction = "down" }))

-- move focused window
-- mainMod + SHIFT + H/L/K/J are not bound elsewhere; safe to bind directly.
hl.bind(mainMod .. " + SHIFT + H", hl.dsp.window.move({ direction = "l" }))
hl.bind(mainMod .. " + SHIFT + L", hl.dsp.window.move({ direction = "r" }))
hl.bind(mainMod .. " + SHIFT + K", hl.dsp.window.move({ direction = "u" }))
hl.bind(mainMod .. " + SHIFT + J", hl.dsp.window.move({ direction = "d" }))

-- disable game mode
-- mainMod + SHIFT + G (GameMode.sh) is disabled: removed from configs/Keybinds.lua instead of unbinding at runtime.

-- close window
-- mainMod + Q (killactive) was removed from configs/Keybinds.lua; kill is remapped to mainMod + SHIFT + Q below.
hl.bind(mainMod .. " + SHIFT + Q", hl.dsp.window.close())

-- Rebind window move to SUPER + SHIFT + Left Click (prevents accidental movement of tiled windows)
-- mainMod + mouse:272 (movewindow) was removed from configs/Keybinds.lua; remapped to mainMod + SHIFT + mouse:272 below.
hl.bind(mainMod .. " + SHIFT + mouse:272", hl.dsp.window.drag(), { mouse = true })

